<script lang="ts">
 import { ApiBadge, Callout, CodeBlock, DescriptionList, Panel, RunOrigin, RunTarget, StatusBadge, StepChecks, StepStatus, WorkflowLoom } from '@microcks/deep-ink';
 import { LOOM_RESTOCK_RUN14, RUN14_FAILURE } from '@microcks-deep-ink/storybook-shared/fixtures';
 let selected = $state<string | undefined>('patchPastry');
