</script>
<div class="sb-col" style="max-width: 1040px"><header class="sb-col"><h1 style="font: var(--type-section); margin: 0">Run #14</h1><div class="inline"><ApiBadge arazzo name="restock-pastry" /><StatusBadge status="failed" label="Failed at patchPastry" /><RunTarget target="mocks" /><RunOrigin origin="ui" /></div></header><Callout tone="danger" title="Run failed">{RUN14_FAILURE.summary}</Callout><WorkflowLoom {...LOOM_RESTOCK_RUN14} selectedStep={selected} onstepselect={e => selected = e.stepId} />{#if step}<Panel title={`Step: ${step.stepId}`} headingLevel={2}><div class="sb-col"><DescriptionList items={[{ term: 'Operation', value: step.operation, mono: true }, { term: 'Source', value: step.source }, { term: 'Attempts', value: String(step.attempts ?? 0) }]} /><div class="inline"><StepStatus status={step.status ?? 'not-run'} attempts={step.attempts && step.attempts > 1 ? step.attempts : undefined} />{#if step.checks && !Array.isArray(step.checks)}<StepChecks successCriteria={step.checks.successCriteria} schemaValidation={step.checks.schemaValidation} />{/if}</div>{#if step.stepId === 'patchPastry'}<CodeBlock caption={`${RUN14_FAILURE.request} · response`} language="json" lines={RUN14_FAILURE.response} />{/if}</div></Panel>{/if}</div>
